export function Tagline({
  text = "{{text}}",
  align = "{{align}}",
  color = "{{color}}",
  showRule = {{showRule}},
}) {
  const centered = align === "center";
  return (
    <p style={{ font: "700 24px/1.4 system-ui, sans-serif", margin: 0, padding: "8px 0", textAlign: align, color }}>
      {text}
      {showRule && (
        <span style={{ display: "block", width: 56, height: 4, borderRadius: 2, marginTop: 10, background: color,
          marginLeft: centered ? "auto" : 0, marginRight: centered ? "auto" : 0 }} />
      )}
    </p>
  );
}
